-- Run against a fresh disposable database built through migration 016.
do $guard$ begin if current_setting('app.disposable_test', true) is distinct from 'true' then raise exception 'disposable_database_guard_required'; end if; end $guard$;
create function pg_temp.assert_true(p_condition boolean, p_case text) returns void language plpgsql as $assert$
begin if not coalesce(p_condition, false) then raise exception using errcode = 'P0001', message = p_case; end if; end $assert$;
insert into public.profiles (id, email, credits) values
  ('user_017_a', 'a@example.invalid', 0), ('user_017_b', 'b@example.invalid', 0), ('user_017_fail', 'fail@example.invalid', 0);
insert into public.products (id, title, slug, description, price, size, color, category, image_urls, status) values
  ('17000000-0000-0000-0000-000000000001', 'One', 'one-017', 'fixture', 100, 'M', 'black', 'fixture', '{}', 'available'),
  ('17000000-0000-0000-0000-000000000002', 'Two', 'two-017', 'fixture', 200, 'M', 'black', 'fixture', '{}', 'available'),
  ('17000000-0000-0000-0000-000000000003', 'Three', 'three-017', 'fixture', 300, 'M', 'black', 'fixture', '{}', 'available'),
  ('17000000-0000-0000-0000-000000000004', 'Sold', 'sold-017', 'fixture', 400, 'M', 'black', 'fixture', '{}', 'sold');
create temp table order_a as select * from public.create_product_checkout('user_017_a', '{"email":"a@example.invalid","fullName":"A User"}'::jsonb, array['17000000-0000-0000-0000-000000000001'::uuid], 50);
select pg_temp.assert_true((select count(*) = 1 from public.orders where id = (select order_id from order_a) and integrity_version = 1 and user_id = 'user_017_a' and payment_amount = 150 and payment_currency = 'ARS') and (select count(*) = 1 from public.order_items where order_id = (select order_id from order_a) and integrity_version = 1) and (select count(*) = 1 from public.inventory_reservations where order_id = (select order_id from order_a) and status = 'active') and (select status = 'reserved' from public.products where id = '17000000-0000-0000-0000-000000000001'), 'atomic_checkout_missing_authority');
do $invalid$ begin
  begin perform public.create_product_checkout('user_017_a', '{"email":"a@example.invalid","fullName":"A User"}'::jsonb, array['17000000-0000-0000-0000-000000000002'::uuid, '17000000-0000-0000-0000-000000000002'::uuid], 0); raise exception 'duplicate_selection_admitted'; exception when raise_exception then if sqlerrm = 'duplicate_selection_admitted' then raise; end if; end;
  begin perform public.create_product_checkout('user_017_a', '{"email":"a@example.invalid","fullName":"A User"}'::jsonb, array['17000000-0000-0000-0000-000000000004'::uuid], 0); raise exception 'unavailable_selection_admitted'; exception when raise_exception then if sqlerrm = 'unavailable_selection_admitted' then raise; end if; end;
  begin perform public.create_product_checkout('user_017_a', '{"email":"a@example.invalid","fullName":"A User"}'::jsonb, array['17000000-0000-0000-0000-000000000099'::uuid], 0); raise exception 'missing_selection_admitted'; exception when raise_exception then if sqlerrm = 'missing_selection_admitted' then raise; end if; end;
  begin perform public.create_product_checkout(null, '{"email":"a@example.invalid","fullName":"A User"}'::jsonb, array['17000000-0000-0000-0000-000000000002'::uuid], 0); raise exception 'guest_checkout_admitted'; exception when raise_exception then if sqlerrm = 'guest_checkout_admitted' then raise; end if; end;
end $invalid$;
select pg_temp.assert_true((select count(*) = 1 from public.orders where integrity_version = 1) and (select count(*) = 1 from public.inventory_reservations where status = 'active'), 'invalid_selection_left_residue');
create temp table order_b as select * from public.create_product_checkout('user_017_b', '{"email":"b@example.invalid","fullName":"B User"}'::jsonb, array['17000000-0000-0000-0000-000000000002'::uuid], 0);
select pg_temp.assert_true(public.cancel_product_order((select order_id from order_a), 'preference_failed', 'preference_failed'), 'owned_cancellation_failed');
select pg_temp.assert_true((select status = 'available' from public.products where id = '17000000-0000-0000-0000-000000000001') and (select status = 'reserved' from public.products where id = '17000000-0000-0000-0000-000000000002') and (select status = 'active' from public.inventory_reservations where order_id = (select order_id from order_b)), 'cross_order_release');
select pg_temp.assert_true(public.expire_product_reservations((select expires_at + interval '1 minute' from order_b), 10) = 1, 'expiry_count_incorrect');
select pg_temp.assert_true((select status = 'cancelled' from public.orders where id = (select order_id from order_b)) and (select status = 'released' from public.inventory_reservations where order_id = (select order_id from order_b)) and (select status = 'available' from public.products where id = '17000000-0000-0000-0000-000000000002'), 'expiry_did_not_release_owner');
create function pg_temp.reject_reservation() returns trigger language plpgsql as $trigger$ begin raise exception 'reservation_rejected'; end $trigger$;
create trigger reject_reservation before insert on public.inventory_reservations for each row when (new.product_id = '17000000-0000-0000-0000-000000000003') execute function pg_temp.reject_reservation();
do $rollback$ begin begin perform public.create_product_checkout('user_017_fail', '{"email":"fail@example.invalid","fullName":"Fail User"}'::jsonb, array['17000000-0000-0000-0000-000000000003'::uuid], 0); raise exception 'partial_failure_not_raised'; exception when raise_exception then if sqlerrm = 'partial_failure_not_raised' then raise; end if; end; end $rollback$;
drop trigger reject_reservation on public.inventory_reservations;
select pg_temp.assert_true(not exists (select 1 from public.orders where user_id = 'user_017_fail') and not exists (select 1 from public.inventory_reservations where product_id = '17000000-0000-0000-0000-000000000003') and (select status = 'available' from public.products where id = '17000000-0000-0000-0000-000000000003'), 'partial_failure_left_residue');
do $constraints$ begin begin insert into public.inventory_reservations (order_id, product_id, expires_at, status, released_at) values ((select order_id from order_a), '17000000-0000-0000-0000-000000000003', now(), 'active', now()); raise exception 'invalid_reservation_consistency_admitted'; exception when check_violation then null; end; end $constraints$;
select pg_temp.assert_true(not has_function_privilege('anon', 'public.create_product_checkout(text,jsonb,uuid[],numeric)', 'execute') and has_function_privilege('service_role', 'public.create_product_checkout(text,jsonb,uuid[],numeric)', 'execute'), 'checkout_acl_incorrect');
select count(*) as orders, (select count(*) from public.inventory_reservations) as reservations, (select count(*) from public.products where status = 'reserved') as reserved_products from public.orders where integrity_version = 1;
